-- CA_0192_confirm_controlled_full_name_committee_links.sql
-- Settle the 681 cal_access committee links on ACTIVE rows that CA_0178 kept as needs_research because the committee
-- name carries the person's FULL name ("full name (out of scope)"). A full-name match is not proof: the review found
-- independent committees ("NAZARIAN FOR COUNCIL 2024: SPONSORED BY BIZFED PAC ..."), committees OPPOSING the person
-- ("... OPPOSING PATTY", "CALIFORNIANS TO RECALL GAVIN") and a same-named stranger, all stored as the person's own
-- candidate_committee. This file decides each link from the Secretary of State's own records.
--
-- EVIDENCE: the Cal-Access bulk export, https://campaignfinance.cdn.sos.ca.gov/dbwebexport.zip (1.58 GB, last-modified
-- 2026-09-23, downloaded that day with operator permission; not committed). Read for the 681 committee ids:
-- FILER_TO_FILER_TYPE_CD (CATEGORY 40002 = CONTROLLED, SUB_CATEGORY 40102 = PRIMARILY FORMED CANDIDATE), FILER_LINKS_CD
-- (LINK_TYPE 12011 = CANDIDATE CONTROLS THIS COMMITTEE, and the controlling candidate's FILERNAME_CD name) and the
-- CVR_CAMPAIGN_DISCLOSURE_CD covers (Form 460 / 450 / 497: committee type C, candidate name, office, district).
-- Every link and its reason is in data/roster-audits/2026-09-23-full-name-committee-links-CA_0192.csv. _link.committee is
-- the name STORED in the link's notes (the pre-flight matches on it); 15 committees were renamed at the SOS since
-- (same filer id, e.g. "LIEU 2010, FRIENDS OF TED" -> "LIEU FOR ATTORNEY GENERAL 2010, TED"); the CSV carries both.
--
-- OUTCOME (681):
--   133 CONFIRMED: controlled by this person (category CONTROLLED and/or a 12011 control link), the controlling
--       candidate's name matches the row, and the committee has SOS e-filed reports, so ingestion has data to load.
--       45 people: Adrin Nazarian, Al Muratsuchi, Amy Thomas Howorth, Ana Valencia, Antonio Villaraigosa, Ardy Kassakhian, Bob Blumenfield, Corey Calaycay, Elen Asatryan, Eleni Kounalakis, Fiona Ma, Gavin Newsom, Gloria D. Gray, Isaac G. Bryan, Ivan Altamirano, Jacqui Irwin, Janet Keo Conklin, Jay Obernolte, Jed Leano, Jesse Gabriel, John Harabedian, Josh Fryday, Josh Lowenthal, Juan Carrillo, Judy Chu, Julia Brownley, Karen Ruth Bass, Kelly Honig, Lisa Calderon, Maebe Pudlo, Malia M. Cohen, Mike A. Gipson, Mike Fong, Nayiri Nahabedian, Nick Schultz, Patty Lopez, Pilar Schiavo, Rick Ramirez, Rob Bonta, Sade Elhawary, Steve Hill, Ted W. Lieu, Tom Lackey, Tony Strickland, Tony Thurmond.
--       The office and district on each cover were read against the person's seat and career; every one is a known
--       step of that career (e.g. Bonta: Alameda city council -> Assembly D18 -> Attorney General). Two rows with no seat
--       were checked by hand: Nayiri Nahabedian (former Glendale Unified trustee; 2010 committee is Assembly D43, the
--       Glendale district) and Steve Hill (his confirmed FEC link is House CA-25; his Senate committees are SD21, both
--       Antelope Valley; Ballotpedia and 2016/2020 press coverage name the same Steve Hill). Three confirmed committees are
--       not campaign committees but are controlled by the person: Isaac Bryan's and Jesse Gabriel's ballot-measure
--       committees and Fiona Ma's legal defense fund.
--   63 DISPUTED: Cal-Access category PRIMARILY FORMED CANDIDATE -- independent committees that support or oppose the
--       person. None is theirs; showing its money as their fundraising would be false, and some oppose them.
--   1 DISPUTED: "LUNA FOR JUDGE 2024; BOBBY" is controlled by Bobby Luna, a candidate for judge, not Sheriff Robert Luna.
--   484 UNCHANGED (still needs_research, reason in the CSV):
--     454 controlled committees with NO SOS e-filed reports -- local committees file their Form 460s with the city clerk
--         or county registrar, so the SOS export holds nothing to ingest. Confirming them would switch a local official's
--         campaign-finance panel from 'local_unavailable' (true) to 'data_pending' (false, for ever): detectCoverageStatus
--         returns 'data_pending' for any confirmed candidate committee when no contributions exist.
--      30 candidate filer records (e.g. "HUTT, HEATHER"), not committees: no contributions are filed under them.
--
-- ⚠ CONFIRMED IS NOT THE SAME AS LOADED. Cal-Access ingestion is manual (POST /api/campaign-finance/admin/ingest/
-- cal-access; the SQS path was never deployed, and no job in src/jobs/registry.ts runs it). The last cal_access
-- ingestion run started 2026-05-21. Until an ingest runs, the 16 of these 45 people with no contributions from any
-- source show 'data_pending'.
--
-- WHY 'disputed': the admin API's own value for a wrong link (campaignFinanceAdmin.ts), as in CA_0166 - CA_0178.
-- Money: none of the 197 links carries a contribution or a contribution_summary_agg row (measured 2026-09-23); 69
-- historical ingestion_runs keep their source. Nothing is deleted.
-- NOTES FORMAT: 196 notes are "<json> | <text>" and get a " | CONFIRMED by / DISPUTED by CA_0192 (2026-09-23): <reason>" suffix; the
-- JSON head that read paths parse (committee_name) is untouched. 1 (the Bobby Luna link) is a plain JSON object and gets
-- disputed_by / disputed_reason keys (IS JSON OBJECT branch, as in CA_0174 and CA_0178). politician_sources is
-- public-read: no reason carries a phone number.
--
-- No migration runner exists; this file records SQL applied by hand (pure DML).
-- STATUS: APPLIED to prod 2026-09-23 (operator approval: Chris Andrews). Dry run x2 with a snapshot control and a planted
--   population control (tripped) right before the apply; re-run after it changed nothing. Verified after: the 681 links
--   read 133 confirmed / 64 disputed / 484 needs_research (snapshot md5 identical to the dry run's in-transaction one);
--   active cal_access links: confirmed 173 -> 306, disputed 654 -> 718, needs_research 1,197 -> 1,000.
--
-- ROLLBACK:
--   UPDATE transparent_motivations.politician_sources
--      SET research_status = 'needs_research',
--          notes = CASE WHEN notes IS JSON OBJECT THEN (notes::jsonb - 'disputed_by' - 'disputed_reason')::text
--                       ELSE left(notes, strpos(notes, ' | ' || CASE research_status WHEN 'confirmed' THEN 'CONFIRMED' ELSE 'DISPUTED' END
--                                                          || ' by CA_0192 (2026-09-23): ') - 1) END
--    WHERE strpos(notes, 'CA_0192 (2026-09-23)') > 0 AND research_status IN ('confirmed', 'disputed');
-- IDEMPOTENT: the update is guarded on research_status = 'needs_research'; a re-run changes nothing and every gate passes.

BEGIN;

CREATE TEMP TABLE _link (id uuid PRIMARY KEY, politician_id uuid, external_id text, committee text,
                         new_status text, reason text) ON COMMIT DROP;

-- the whole reviewed population (681), decided or left
CREATE TEMP TABLE _reviewed (id uuid PRIMARY KEY) ON COMMIT DROP;

-- contributions holds ~28M rows: count per link through its politician_source_id index, never by a join the planner
-- may turn into a scan of the whole table.
ANALYZE _link;
ANALYZE _reviewed;

CREATE TEMP TABLE _before ON COMMIT DROP AS
SELECT (SELECT count(*) FROM transparent_motivations.politician_sources ps JOIN essentials.politicians p ON p.id = ps.essentials_politician_id
         WHERE p.is_active AND ps.research_status = 'confirmed' AND strpos(ps.notes, 'CA_0192 (2026-09-23)') = 0) AS active_confirmed_other,
       (SELECT count(*) FROM transparent_motivations.politician_sources ps JOIN essentials.politicians p ON p.id = ps.essentials_politician_id
         WHERE p.is_active AND ps.research_status = 'disputed' AND strpos(ps.notes, 'CA_0192 (2026-09-23)') = 0) AS active_disputed_other,
       (SELECT count(*) FROM transparent_motivations.politician_sources ps JOIN essentials.politicians p ON p.id = ps.essentials_politician_id
         WHERE p.is_active AND ps.research_status = 'not_applicable') AS active_not_applicable,
       (SELECT sum((SELECT count(*) FROM transparent_motivations.contributions c WHERE c.politician_source_id = l.id)) FROM _link l) AS contributions;

-- ─── Pre-flight ──────────────────────────────────────────────────────────────────────────────────
DO $$
DECLARE v_n int; v_md5 text;
BEGIN
  SELECT count(*) INTO v_n FROM _link;
  IF v_n <> 197 THEN RAISE EXCEPTION 'PRE: _link holds %, expected 197', v_n; END IF;
  SELECT count(*) INTO v_n FROM _link WHERE new_status = 'confirmed';
  IF v_n <> 133 THEN RAISE EXCEPTION 'PRE: % links to confirm, expected 133', v_n; END IF;

  -- each link is the recorded (row, committee id, stored committee name), cal_access, on an ACTIVE row, still
  -- needs_research (or already set by an earlier run of this file)
  SELECT count(*) INTO v_n FROM _link l
    JOIN transparent_motivations.politician_sources ps ON ps.id = l.id
    JOIN essentials.politicians p ON p.id = ps.essentials_politician_id
   WHERE ps.essentials_politician_id = l.politician_id AND ps.source_system = 'cal_access'
     AND ps.external_id = l.external_id AND ps.source_type = 'candidate_committee'
     AND COALESCE(split_part(ps.notes, ' | ', 1)::jsonb ->> 'committee_name',
                  split_part(ps.notes, ' | ', 1)::jsonb ->> 'cmt_nm') = l.committee
     AND (ps.research_status = 'needs_research' OR (ps.research_status = l.new_status AND strpos(ps.notes, 'CA_0192 (2026-09-23)') > 0))
     AND p.is_active;
  IF v_n <> 197 THEN RAISE EXCEPTION 'PRE: % of 197 links match their reviewed record on an active row', v_n; END IF;

  -- the reviewed population is intact: 681 links, pinned by an md5 of the sorted ids, each still needs_research or
  -- set by this file. A link moved, re-pointed or re-statused since the review fails here.
  SELECT count(*), md5(string_agg(ps.id::text, ',' ORDER BY ps.id)) INTO v_n, v_md5
    FROM _reviewed r JOIN transparent_motivations.politician_sources ps ON ps.id = r.id
    JOIN essentials.politicians p ON p.id = ps.essentials_politician_id
   WHERE p.is_active AND ps.source_system = 'cal_access'
     AND (ps.research_status = 'needs_research' OR strpos(ps.notes, 'CA_0192 (2026-09-23)') > 0);
  IF v_n <> 681 OR v_md5 <> 'fa0f20340029779346b6e24d159ab783' THEN
    RAISE EXCEPTION 'PRE: the reviewed population changed: % links, md5 % (expected 681, fa0f20340029779346b6e24d159ab783)', v_n, v_md5;
  END IF;
END $$;

-- ─── Confirm 133, dispute 64 ─────────────────────────────────────────────────────────────────────
UPDATE transparent_motivations.politician_sources ps
   SET research_status = l.new_status,
       notes = CASE WHEN ps.notes IS JSON OBJECT
                    THEN (ps.notes::jsonb || CASE l.new_status
                            WHEN 'confirmed' THEN jsonb_build_object('confirmed_by', 'CA_0192 (2026-09-23)', 'confirmed_reason', l.reason)
                            ELSE jsonb_build_object('disputed_by', 'CA_0192 (2026-09-23)', 'disputed_reason', l.reason) END)::text
                    ELSE ps.notes || ' | ' || CASE l.new_status WHEN 'confirmed' THEN 'CONFIRMED' ELSE 'DISPUTED' END
                         || ' by CA_0192 (2026-09-23): ' || l.reason END,
       updated_at = now()
  FROM _link l
 WHERE ps.id = l.id AND ps.research_status = 'needs_research';

-- ─── Post-verify gate ────────────────────────────────────────────────────────────────────────────
DO $$
DECLARE v_n int; b record;
BEGIN
  SELECT * INTO b FROM _before;

  SELECT count(*) INTO v_n FROM transparent_motivations.politician_sources ps JOIN _link l ON l.id = ps.id
   WHERE ps.research_status = l.new_status
     AND ((ps.notes IS JSON OBJECT AND ps.notes::jsonb ->> (CASE l.new_status WHEN 'confirmed' THEN 'confirmed' ELSE 'disputed' END || '_by') = 'CA_0192 (2026-09-23)')
          OR right(ps.notes, length(' by CA_0192 (2026-09-23): ' || l.reason)) = ' by CA_0192 (2026-09-23): ' || l.reason);
  IF v_n <> 197 THEN RAISE EXCEPTION 'POST: % of 197 links carry their new status and reason', v_n; END IF;

  SELECT count(*) INTO v_n FROM transparent_motivations.politician_sources ps
   WHERE strpos(ps.notes, 'CA_0192 (2026-09-23)') > 0 AND NOT EXISTS (SELECT 1 FROM _link l WHERE l.id = ps.id);
  IF v_n <> 0 THEN RAISE EXCEPTION 'POST: % link(s) outside _link carry the CA_0192 (2026-09-23) marker', v_n; END IF;

  -- the 484 left links are untouched
  SELECT count(*) INTO v_n FROM _reviewed r JOIN transparent_motivations.politician_sources ps ON ps.id = r.id
   WHERE NOT EXISTS (SELECT 1 FROM _link l WHERE l.id = r.id) AND ps.research_status = 'needs_research'
     AND strpos(ps.notes, 'CA_0192 (2026-09-23)') = 0;
  IF v_n <> 484 THEN RAISE EXCEPTION 'POST: % of 484 left links still needs_research and unmarked', v_n; END IF;

  -- nothing else on active rows moved
  SELECT count(*) INTO v_n FROM transparent_motivations.politician_sources ps JOIN essentials.politicians p ON p.id = ps.essentials_politician_id
   WHERE p.is_active AND ps.research_status = 'confirmed' AND strpos(ps.notes, 'CA_0192 (2026-09-23)') = 0;
  IF v_n <> b.active_confirmed_other THEN RAISE EXCEPTION 'POST: other confirmed links moved % -> %', b.active_confirmed_other, v_n; END IF;
  SELECT count(*) INTO v_n FROM transparent_motivations.politician_sources ps JOIN essentials.politicians p ON p.id = ps.essentials_politician_id
   WHERE p.is_active AND ps.research_status = 'disputed' AND strpos(ps.notes, 'CA_0192 (2026-09-23)') = 0;
  IF v_n <> b.active_disputed_other THEN RAISE EXCEPTION 'POST: other disputed links moved % -> %', b.active_disputed_other, v_n; END IF;
  SELECT count(*) INTO v_n FROM transparent_motivations.politician_sources ps JOIN essentials.politicians p ON p.id = ps.essentials_politician_id
   WHERE p.is_active AND ps.research_status = 'not_applicable';
  IF v_n <> b.active_not_applicable THEN RAISE EXCEPTION 'POST: not_applicable links moved % -> %', b.active_not_applicable, v_n; END IF;

  -- no money moved (this file changes status only)
  SELECT sum((SELECT count(*) FROM transparent_motivations.contributions c WHERE c.politician_source_id = l.id)) INTO v_n FROM _link l;
  IF v_n <> b.contributions THEN RAISE EXCEPTION 'POST: contributions on these links moved % -> %', b.contributions, v_n; END IF;

  RAISE NOTICE 'CA_0192 applied: 133 links confirmed (45 people), 64 disputed, 484 left needs_research';
END $$;

COMMIT;
